def compute(vars):
    threshold = 500000
    revenues = [vars["v1"], vars["v2"], vars["v3"]]
    qualifying_years = [revenue for revenue in revenues if revenue > threshold]
    return {
        "value": len(qualifying_years),
        "trace": {
            "threshold": threshold,
            "qualifying_years": len(qualifying_years),
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "years"
            }
        }
    }
